questionvariables.text:
/* Design: classify pattern (one dropdown and one response tree per object). Kind code 1: turning point with nonzero second derivative; 2: turning point with zero second derivative (the target misconception); 3: point of inflection. Source: original. */
L: [[[x^4,2,2],[x^3,3,3],[-3*x^2,1,1],[x^3+2*x^2,2,1]],[[x^2,2,1],[-x^4,1,2],[x^4+x^3,3,3],[x^3,3,3]],[[-2*x^3,3,3],[x^4+3*x^2,2,1],[5-x^4,1,2],[x^3-x^2,1,1]],[[x^4-2*x^3,3,3],[-3*x^2,1,1],[x^4,2,2],[x^5,3,3]],[[x^3+4,3,3],[2*x^4-x^2,1,1],[x^2,2,1],[-x^4,1,2]],[[-x^4,1,2],[x^3+2*x^2,2,1],[x^4+x^3,3,3],[x^4+3*x^2,2,1]],[[x^5,3,3],[x^2,2,1],[x^3-x^2,1,1],[5-x^4,1,2]],[[x^4,2,2],[-2*x^3,3,3],[x^3+2*x^2,2,1],[2*x^4-x^2,1,1]],[[x^4+x^3,3,3],[-3*x^2,1,1],[x^4,2,2],[x^3+4,3,3]],[[5-x^4,1,2],[x^4-2*x^3,3,3],[x^4+3*x^2,2,1],[x^3-x^2,1,1]]];
ix: 1+rand(10);
c1: L[ix][1][1]; n1: L[ix][1][2]; kd1: L[ix][1][3];
d1: diff(c1,x); v1: ev(diff(c1,x,2),x=0); gl1: ev(d1,x=-1/10); gr1: ev(d1,x=1/10);
nat1: [["max1",is(n1=1),"maximum point"],["min1",is(n1=2),"minimum point"],["inf1",is(n1=3),"point of inflection"]];
wa1: if kd1=3 then "max1" elseif kd1=2 then "inf1" elseif n1=1 then "min1" else "max1";
wb1: if kd1=3 then "min1" elseif kd1=2 then (if n1=1 then "min1" else "max1") else "inf1";
c2: L[ix][2][1]; n2: L[ix][2][2]; kd2: L[ix][2][3];
d2: diff(c2,x); v2: ev(diff(c2,x,2),x=0); gl2: ev(d2,x=-1/10); gr2: ev(d2,x=1/10);
nat2: [["max2",is(n2=1),"maximum point"],["min2",is(n2=2),"minimum point"],["inf2",is(n2=3),"point of inflection"]];
wa2: if kd2=3 then "max2" elseif kd2=2 then "inf2" elseif n2=1 then "min2" else "max2";
wb2: if kd2=3 then "min2" elseif kd2=2 then (if n2=1 then "min2" else "max2") else "inf2";
c3: L[ix][3][1]; n3: L[ix][3][2]; kd3: L[ix][3][3];
d3: diff(c3,x); v3: ev(diff(c3,x,2),x=0); gl3: ev(d3,x=-1/10); gr3: ev(d3,x=1/10);
nat3: [["max3",is(n3=1),"maximum point"],["min3",is(n3=2),"minimum point"],["inf3",is(n3=3),"point of inflection"]];
wa3: if kd3=3 then "max3" elseif kd3=2 then "inf3" elseif n3=1 then "min3" else "max3";
wb3: if kd3=3 then "min3" elseif kd3=2 then (if n3=1 then "min3" else "max3") else "inf3";
c4: L[ix][4][1]; n4: L[ix][4][2]; kd4: L[ix][4][3];
d4: diff(c4,x); v4: ev(diff(c4,x,2),x=0); gl4: ev(d4,x=-1/10); gr4: ev(d4,x=1/10);
nat4: [["max4",is(n4=1),"maximum point"],["min4",is(n4=2),"minimum point"],["inf4",is(n4=3),"point of inflection"]];
wa4: if kd4=3 then "max4" elseif kd4=2 then "inf4" elseif n4=1 then "min4" else "max4";
wb4: if kd4=3 then "min4" elseif kd4=2 then (if n4=1 then "min4" else "max4") else "inf4";
